package com.ccb.release.production.persistence;
import com.ccb.release.production.model.ProductionModels.Entry; import com.ccb.release.production.model.ProductionModels.Result; import org.springframework.stereotype.Repository; import java.time.LocalDateTime; import java.util.HashMap; import java.util.List; import java.util.Map; import java.util.Optional;
@Repository public class ReleaseProductionStore { private final ReleaseProductionMapper mapper; public ReleaseProductionStore(ReleaseProductionMapper mapper){this.mapper=mapper;} public List<Entry> findBaseline(long tenantId,long windowId){return mapper.baseline(p("tenantId",tenantId,"windowId",windowId));} public Optional<Entry> findActiveForUpdate(long tenantId,long windowId,String subsystemCode,String itemKey){return Optional.ofNullable(mapper.activeForUpdate(p("tenantId",tenantId,"windowId",windowId,"subsystemCode",subsystemCode,"itemKey",itemKey)));} public Optional<Entry> findBySource(long tenantId,long windowId,long applicationId,String itemKey){return Optional.ofNullable(mapper.bySource(p("tenantId",tenantId,"windowId",windowId,"applicationId",applicationId,"itemKey",itemKey)));} public Optional<Entry> findByIdForUpdate(long id,long tenantId){return Optional.ofNullable(mapper.byIdForUpdate(p("id",id,"tenantId",tenantId)));} public Optional<Entry> findById(long id,long tenantId){return Optional.ofNullable(mapper.byId(p("id",id,"tenantId",tenantId)));} public void deactivate(long id,long tenantId,long operatorId){mapper.deactivate(p("id",id,"tenantId",tenantId,"operatorId",operatorId));} public void activate(long id,long tenantId,long operatorId){mapper.activate(p("id",id,"tenantId",tenantId,"operatorId",operatorId));} public void insert(Entry v,long operatorId){Map<String,Object> p=entry(v);p.put("operatorId",operatorId);mapper.insert(p);} public boolean updateResult(long id,long tenantId,long version,Result result,LocalDateTime productionAt,String resultReason,long operatorId){return mapper.updateResult(p("id",id,"tenantId",tenantId,"version",version,"result",result.name(),"productionAt",productionAt,"resultReason",resultReason,"operatorId",operatorId))==1;} public void appendResultLog(long id,long tenantId,Entry before,Result result,LocalDateTime productionAt,String reason,long operatorId,String operatorName){mapper.appendResultLog(p("id",id,"tenantId",tenantId,"entryId",before.id(),"fromResult",before.productionResult().name(),"toResult",result.name(),"reason",reason,"beforeAt",before.productionAt(),"afterAt",productionAt,"operatorId",operatorId,"operatorName",operatorName));} public List<Entry> findCurrentVersions(long tenantId,String projectId){return mapper.currentVersions(p("tenantId",tenantId,"projectId",projectId==null||projectId.isBlank()?null:projectId.trim()));} public List<Entry> findHistory(long tenantId,String subsystemCode,String deliveryCode){return mapper.history(p("tenantId",tenantId,"subsystemCode",subsystemCode,"deliveryCode",deliveryCode));} public List<Entry> findHistoryByItemKey(long tenantId,String subsystemCode,String itemKey){return mapper.historyByItemKey(p("tenantId",tenantId,"subsystemCode",subsystemCode,"itemKey",itemKey));} private static Map<String,Object> entry(Entry v){return p("id",v.id(),"tenantId",v.tenantId(),"windowId",v.windowId(),"applicationId",v.applicationId(),"applicationCode",v.applicationCode(),"approvedAt",v.approvedAt(),"subsystemId",v.subsystemId(),"subsystemCode",v.subsystemCode(),"subsystemName",v.subsystemName(),"deliveryUnitId",v.deliveryUnitId(),"deliveryUnitCode",v.deliveryUnitCode(),"deliveryUnitName",v.deliveryUnitName(),"artifactType",v.artifactType(),"artifactVersion",v.artifactVersion(),"itemType",v.itemType(),"filePath",v.filePath(),"itemKey",v.itemKey(),"versionType",v.versionType(),"characteristic",v.characteristic(),"productionResult",v.productionResult().name(),"productionAt",v.productionAt(),"resultReason",v.resultReason(),"activeCandidate",v.activeCandidate());} private static Map<String,Object> p(Object... values){Map<String,Object> p=new HashMap<>();for(int i=0;i<values.length;i+=2)p.put((String)values[i],values[i+1]);return p;} }
